-- โหลดข้อมูล mock เข้า PostgreSQL (รันหลัง schema.sql)   ใช้:  psql -d <db> -f load.sql   (ให้รันจากโฟลเดอร์ csv/)
-- หมายเหตุ: app_user_role_history ถูกสร้างอัตโนมัติจาก trigger ตอนโหลด app_user; audit_log/forecast_*/agent_* ปล่อยว่างให้ระบบสร้างเอง
\set ON_ERROR_STOP on
SET session_replication_role = origin;
\copy region (id,code,name_th,name_en,created_at) FROM 'region.csv' WITH (FORMAT csv, HEADER true)
\copy network (id,region_id,name,auto_approve) FROM 'network.csv' WITH (FORMAT csv, HEADER true)
\copy hospital (id,region_id,network_id,code,name_th,name_en,lat,lon,is_urban,has_cold_chain,has_blood_bank,active,created_at,updated_at,version) FROM 'hospital.csv' WITH (FORMAT csv, HEADER true)
\copy app_user (id,cognito_sub,email,display_name,role,hospital_id,region_id,phone,active,created_at) FROM 'app_user.csv' WITH (FORMAT csv, HEADER true)
\copy hospital_distance (from_hospital_id,to_hospital_id,distance_km,duration_min_normal,duration_min_peak,travel_minutes,travel_minutes_override,source,refreshed_at) FROM 'hospital_distance.csv' WITH (FORMAT csv, HEADER true)
\copy config_setting (key,scope,value,description,updated_by,updated_at) FROM 'config_setting.csv' WITH (FORMAT csv, HEADER true)
\copy drug_master (id,item_type,gp_id,internal_code,generic_name,strength,dosage_form,base_unit,is_cold_chain,is_blood_product,is_high_alert,emergency_class,created_at) FROM 'drug_master.csv' WITH (FORMAT csv, HEADER true)
\copy tmt_reference (tmt_id,level,name,parent_tmt_id,gp_id) FROM 'tmt_reference.csv' WITH (FORMAT csv, HEADER true)
\copy hospital_drug (id,hospital_id,local_code,local_name,unit_price_thb,local_unit,tmt_id,gp_id,active,ved,abc,expiry_threshold_days,drug_master_id) FROM 'hospital_drug.csv' WITH (FORMAT csv, HEADER true)
\copy drug_mapping (id,hospital_drug_id,drug_master_id,status,method,confidence,unit_conversion_factor,local_pack_unit,base_units_per_pack,manufacturer,suggested_by,verified_by,verified_at,reject_reason,created_at,updated_at,version) FROM 'drug_mapping.csv' WITH (FORMAT csv, HEADER true)
\copy mapping_candidate (id,drug_mapping_id,tmt_id,score,score_parts,rank) FROM 'mapping_candidate.csv' WITH (FORMAT csv, HEADER true)
\copy drug_mapping_history (drug_mapping_id,from_status,to_status,actor_id,note,occurred_at) FROM 'drug_mapping_history.csv' WITH (FORMAT csv, HEADER true)
\copy hospital_import (id,hospital_id,kind,file_key,rows_total,rows_ok,rows_error,errors,created_by,created_at) FROM 'hospital_import.csv' WITH (FORMAT csv, HEADER true)
\copy stock_lot (id,hospital_id,hospital_drug_id,lot_no,expiry_date,manufacturer,pack_size_base_units,qty_on_hand,qty_held,updated_at,version) FROM 'stock_lot.csv' WITH (FORMAT csv, HEADER true)
\copy stock_ledger (hospital_id,lot_id,delta,reason,ref_type,ref_id,occurred_at,actor_id) FROM 'stock_ledger.csv' WITH (FORMAT csv, HEADER true)
\copy stock_snapshot (hospital_id,hospital_drug_id,snap_date,qty_on_hand,qty_incoming,qty_held) FROM 'stock_snapshot.csv' WITH (FORMAT csv, HEADER true)
\copy usage_daily (hospital_id,hospital_drug_id,usage_date,qty_used) FROM 'usage_daily.csv' WITH (FORMAT csv, HEADER true)
\copy incoming_order (id,hospital_id,hospital_drug_id,qty,expected_date,status,lead_time_days) FROM 'incoming_order.csv' WITH (FORMAT csv, HEADER true)
\copy context_signal (id,region_id,signal_type,payload,valid_from,valid_to,source,approved_by,created_at) FROM 'context_signal.csv' WITH (FORMAT csv, HEADER true)
\copy stock_alert (id,hospital_id,hospital_drug_id,type,severity,status,stock_qty,incoming_qty,days_cover,suggested_borrow_qty,forecast_result_id,snoozed_until,created_at,updated_at,version) FROM 'stock_alert.csv' WITH (FORMAT csv, HEADER true)
\copy kit_type (id,code,name,description,needs_cold_chain,active) FROM 'kit_type.csv' WITH (FORMAT csv, HEADER true)
\copy kit_component (kit_type_id,drug_master_id,qty_per_kit) FROM 'kit_component.csv' WITH (FORMAT csv, HEADER true)
\copy kit_recipe (triage,kit_type_id,qty_per_patient,is_critical_min) FROM 'kit_recipe.csv' WITH (FORMAT csv, HEADER true)
\copy incident_extra_rule (triage,drug_master_id,qty_per_patient,is_critical_min) FROM 'incident_extra_rule.csv' WITH (FORMAT csv, HEADER true)
\copy incident (id,incident_no,hospital_id,status,location_lat,location_lon,location_text,reported_eta_min,created_by,duplicate_of,closed_at,created_at,updated_at,version) FROM 'incident.csv' WITH (FORMAT csv, HEADER true)
\copy incident_patient_count (incident_id,triage,count,updated_at) FROM 'incident_patient_count.csv' WITH (FORMAT csv, HEADER true)
\copy emergency_plan (id,incident_id,revision,status,estimated_need,critical_min,buffer,steps,shortfall,approved_by,approved_at,agent_run_id,created_at) FROM 'emergency_plan.csv' WITH (FORMAT csv, HEADER true)
\copy kit_pack_task (id,plan_id,hospital_id,kit_type_id,qty,status,confirmed_by,confirmed_at) FROM 'kit_pack_task.csv' WITH (FORMAT csv, HEADER true)
\copy incident_usage (id,incident_id,drug_master_id,kit_type_id,qty_used,recorded_by) FROM 'incident_usage.csv' WITH (FORMAT csv, HEADER true)
\copy borrow_request (id,request_no,borrower_hospital_id,context,status,urgency,stock_alert_id,incident_id,reason,created_by,approved_by,approved_at,ladder,first_round_qty,stop_threshold,created_at,updated_at,version) FROM 'borrow_request.csv' WITH (FORMAT csv, HEADER true)
\copy borrow_request_item (id,request_id,kind,drug_master_id,kit_type_id,qty_requested,qty_fulfilled,r_value) FROM 'borrow_request_item.csv' WITH (FORMAT csv, HEADER true)
\copy borrow_leg (id,request_id,lender_hospital_id,round_no,rank_in_ladder,status,score_si,score_parts,t_transit_min,window_max_days,qty_asked,qty_accepted,qty_received,sent_at,deadline_at,reminded_at,responded_at,responded_by,reject_reason,message_text) FROM 'borrow_leg.csv' WITH (FORMAT csv, HEADER true)
\copy borrow_leg_lot (id,leg_id,lot_id,qty) FROM 'borrow_leg_lot.csv' WITH (FORMAT csv, HEADER true)
\copy return_obligation (id,leg_id,debtor_hospital_id,creditor_hospital_id,drug_master_id,kit_type_id,qty,qty_returned,return_mode,due_date,status,returned_at,waived_reason,waived_by) FROM 'return_obligation.csv' WITH (FORMAT csv, HEADER true)
\copy return_receipt (id,obligation_id,drug_master_id,lot_id,qty_local,qty_base,received_by,received_at) FROM 'return_receipt.csv' WITH (FORMAT csv, HEADER true)
\copy reliability_stat (lender_hospital_id,month,requests_received,accepted_on_time) FROM 'reliability_stat.csv' WITH (FORMAT csv, HEADER true)
\copy near_expiry_item (id,hospital_id,lot_id,status,qty,days_left,value_thb,decided_by,decided_at,note,review_after,created_at,updated_at,version) FROM 'near_expiry_item.csv' WITH (FORMAT csv, HEADER true)
\copy pool_entry (id,region_id,near_expiry_item_id,qty_available,released_at) FROM 'pool_entry.csv' WITH (FORMAT csv, HEADER true)
\copy allocation_plan (id,plan_no,region_id,pool_entry_id,status,total_value_thb,total_transport_cost_thb,cost_ratio,economical,option_chosen,agent_run_id,approval_deadline,created_at,updated_at,version) FROM 'allocation_plan.csv' WITH (FORMAT csv, HEADER true)
\copy allocation_line (id,plan_id,receiver_hospital_id,qty,value_thb,expected_use_before_expiry,distance_km,transport_cost_thb,cold_chain) FROM 'allocation_line.csv' WITH (FORMAT csv, HEADER true)
\copy plan_approval (id,plan_id,hospital_id,decision,decided_by,decided_at,comment) FROM 'plan_approval.csv' WITH (FORMAT csv, HEADER true)
\copy transport_task (id,ref_type,ref_id,from_hospital_id,to_hospital_id,status,driver_id,cancel_requested_by,cancel_consent_by,loaded_at,departed_at,arrived_at,received_at,created_at,updated_at,version) FROM 'transport_task.csv' WITH (FORMAT csv, HEADER true)
\copy transport_event (id,task_id,client_event_id,seq,to_status,captured_at,received_at,actor_id,photo_keys,applied,reject_reason) FROM 'transport_event.csv' WITH (FORMAT csv, HEADER true)
\copy repeat_expiry_flag (id,hospital_id,drug_master_id,level,lots_12m,value_12m_thb,suggestion,dismissed_until,created_at) FROM 'repeat_expiry_flag.csv' WITH (FORMAT csv, HEADER true)
\copy kit_stock (hospital_id,kit_type_id,qty_ready,qty_held,updated_at) FROM 'kit_stock.csv' WITH (FORMAT csv, HEADER true)
\copy regional_warehouse_stock (region_id,drug_master_id,qty,updated_at) FROM 'regional_warehouse_stock.csv' WITH (FORMAT csv, HEADER true)
\copy value_record (id,hospital_id,region_id,metric,period,value_thb,value_qty,ref_type,ref_id,detail,created_at) FROM 'value_record.csv' WITH (FORMAT csv, HEADER true)
\copy report_definition (id,name,description,query_spec,roles) FROM 'report_definition.csv' WITH (FORMAT csv, HEADER true)
ANALYZE;
